using Optimus.Core;
var tests=new List<(string,Action)>();void Test(string n,Action a)=>tests.Add((n,a));void Check(bool b,string m){if(!b)throw new Exception(m);}void Throws(Action a){bool caught=false;try{a();}catch(ArgumentException){caught=true;}Check(caught,"Expected validation rejection");}
var rules=new PrivacyPolicy([new("example.org",PrivacyAction.Private),new("blocked.example.org",PrivacyAction.Block),new("exact.test",PrivacyAction.Private,false),new("xn--bcher-kva.example",PrivacyAction.Private)]);
Test("Host boundary exact subdomain and lookalikes",()=>{Check(rules.Evaluate(new("https://example.org"))==PrivacyAction.Private,"Exact protected");Check(rules.Evaluate(new("https://a.example.org"))==PrivacyAction.Private,"Subdomain protected");foreach(var host in new[]{"example.org.evil.test","notexample.org","sub.exact.test"})Check(rules.Evaluate(new("https://"+host))==PrivacyAction.Allow,"Lookalike/exact excluded");});
Test("IDN canonicalization and trailing root dot",()=>{Check(PrivacyPolicy.NormalizeDomain("BÜCHER.Example.")=="xn--bcher-kva.example","IDN canonical");Check(rules.Evaluate(new("https://bücher.example"))==PrivacyAction.Private,"Unicode matched");Check(rules.Evaluate(new("https://example.org./"))==PrivacyAction.Private,"Root dot matched");});
Test("Block wins private remains sticky protected workers blocked universally",()=>{Check(rules.Evaluate(new("https://blocked.example.org"),true)==PrivacyAction.Block,"Block wins");Check(rules.Evaluate(new("https://unknown.test"),true)==PrivacyAction.Private,"Sticky private");Check(rules.Evaluate(new("https://example.org"),true,true)==PrivacyAction.Block,"Private worker conservatively blocked");Check(rules.Evaluate(new("https://example.org"),false,true)==PrivacyAction.Block,"Normal worker blocked");});
Test("Rules reject paths credentials wildcard ports invalid labels and cap",()=>{foreach(var d in new[]{"https://example.org","user@example.org","example.org/path","*.example.org","example.org:80","-bad.test","a..test","example.org?x=1","example.org#fragment"," example.org"})Throws(()=>PrivacyPolicy.NormalizeDomain(d));Throws(()=>PrivacyPolicy.ValidateRules(Enumerable.Range(0,1001).Select(i=>new PrivacyRule("a"+i+".test",PrivacyAction.Private)).ToArray()));Throws(()=>PrivacyPolicy.ValidateRules([new("example.org",PrivacyAction.Allow)]));});
Test("Declared seeds editable and protected",()=>{var seeds=PrivacyPolicy.Seeds();Check(seeds.Count is >0 and <20,"Small declared seed");Check(seeds.All(r=>r.Action==PrivacyAction.Private),"Seeds only private");seeds.Clear();Check(PrivacyPolicy.Seeds().Count>0,"Caller can edit own rules");});
Test("Private protected blocked and ephemeral never enter persistence or closed lists",()=>{Check(rules.CanPersist("https://public.test"),"Normal allowed");Check(!rules.CanPersist("https://public.test",true),"Private excluded");Check(!rules.CanPersist("https://public.test",false,true),"Search excluded");foreach(var url in new[]{"https://example.org","https://blocked.example.org","https://user:pass@public.test","about:blank"})Check(!rules.CanPersist(url),"Protected or invalid excluded");});
Test("Queued callback invalidated by navigation policy change and disposal",()=>{var e=new NavigationEpoch();var lease=e.Capture(2);Check(e.IsCurrent(lease,2),"Fresh accepted");Check(!e.IsCurrent(lease,3),"Rule generation rejected");e.Invalidate();Check(!e.IsCurrent(lease,2),"Navigation invalidates");lease=e.Capture(2);e.Dispose();Check(!e.IsCurrent(lease,2),"Dispose invalidates");});
Test("Settings old providers and preferences roundtrip new default Optimus",()=>{var dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());Directory.CreateDirectory(dir);var path=Path.Combine(dir,"s.json");try{var s=new SettingsStore(path);Check((int)new BrowserSettings().SearchProvider==2,"New profile Optimus default");foreach(var provider in new[]{0,1}){File.WriteAllText(path,"{\"SearchProvider\":"+provider+",\"TextScale\":1.5,\"HighContrast\":true,\"RestoreSession\":true,\"SessionUrls\":[\"https://public.test\"],\"Bookmarks\":[{\"Title\":\"Keep\",\"Url\":\"https://public.test\"}]}");var loaded=s.Load();Check(loaded.Error==null&&(int)loaded.Settings.SearchProvider==provider&&loaded.Settings.TextScale==1.5&&loaded.Settings.HighContrast&&loaded.Settings.Bookmarks.Count==1,"Old values retained");Check(s.Save(loaded.Settings)==null&&s.Load().Settings.SessionUrls.Count==1,"Roundtrip");}}finally{Directory.Delete(dir,true);}});
Test("Settings scrub protected restoration URLs on both save and load",()=>{var dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());Directory.CreateDirectory(dir);var path=Path.Combine(dir,"s.json");try{var s=new SettingsStore(path);var options=new BrowserSettings {RestoreSession=true,PrivacyRules=[new("example.org",PrivacyAction.Private)],SessionUrls=["https://example.org/a?secret=yes","https://public.test"]};Check(s.Save(options)==null,"Save succeeds");Check(!File.ReadAllText(path).Contains("secret=yes")&&s.Load().Settings.SessionUrls.SequenceEqual(new[]{"https://public.test"}),"Protected URL absent from disk");File.WriteAllText(path,"{\"RestoreSession\":true,\"PrivacyRules\":[{\"Domain\":\"example.org\",\"Action\":1}],\"SessionUrls\":[\"https://example.org/private\"]}");Check(s.Load().Settings.SessionUrls.Count==0,"Old protected session not restored");}finally{Directory.Delete(dir,true);}});
Test("Settings validate endpoint and rules before writing",()=>{var dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());Directory.CreateDirectory(dir);try{var s=new SettingsStore(Path.Combine(dir,"s.json"));foreach(var endpoint in new[]{"http://remote.test/search","https://user:pass@remote.test","file:///secret","https://remote.test/#fragment"})Check(s.Save(new() {SearxEndpoint=endpoint})!=null,"Unsafe endpoint rejected");Check(s.Save(new() {PrivacyRules=[new("*.bad.test",PrivacyAction.Private)]})!=null,"Invalid rule rejected");Check(s.Save(new() {PrivacyRules=Enumerable.Range(0,1001).Select(i=>new PrivacyRule("a"+i+".test",PrivacyAction.Private)).ToList()})!=null,"Over cap rejected");}finally{Directory.Delete(dir,true);}});
Test("Only host-controlled known GET may automatically open private",()=>{var protectedUri=new Uri("https://example.org/form");Check(rules.DecideNavigation(protectedUri,false,true)==NavigationDisposition.OpenPrivate,"Known GET selects private first");Check(rules.DecideNavigation(protectedUri,false,false)==NavigationDisposition.OfferPrivate,"Ambiguous engine link/redirect/form cancels and offers, never replays");Check(rules.DecideNavigation(protectedUri,true,false)==NavigationDisposition.Navigate,"Private stays in current private profile");Check(rules.DecideNavigation(new("https://blocked.example.org"),true,true)==NavigationDisposition.Block,"Block wins even host GET private");});
Test("Final private retirement never reuses the old off-record profile identity",()=>{var session=new PrivateSessionIdentity();var first=session.Name;Check(session.Name==first,"Live controls share identity");session.Retire();Check(session.Name!=first&&session.Name.StartsWith("OptimusPrivate",StringComparison.Ordinal),"Final close/recovery retires identity");Check(new PrivateSessionIdentity().Name!=session.Name,"Separate process sessions do not reuse identity");});
Test("Versioned settings migration preserves legacy file and never falls back from corrupt new settings",()=>{var dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());Directory.CreateDirectory(dir);var legacy=Path.Combine(dir,"settings.json");var current=Path.Combine(dir,"settings-v02.json");const string original="{\"SearchProvider\":1,\"TextScale\":1.5,\"HighContrast\":true,\"RestoreSession\":true,\"SessionUrls\":[\"https://example.org/private\",\"https://public.test\"],\"PrivacyRules\":[{\"Domain\":\"example.org\",\"Action\":1}]}";try{File.WriteAllText(legacy,original);var store=new SettingsStore(current,legacy);var imported=store.Load();Check(imported.Error==null&&imported.Settings.SearchProvider==SearchProvider.Google&&imported.Settings.HighContrast&&imported.Settings.TextScale==1.5,"Legacy preferences imported");Check(imported.Settings.SessionUrls.SequenceEqual(new[]{"https://public.test"}),"Protected legacy addresses scrubbed");Check(store.Save(imported.Settings with {SearchProvider=SearchProvider.Optimus})==null&&File.ReadAllText(legacy)==original,"Only versioned settings written");Check(store.Load().Settings.SearchProvider==SearchProvider.Optimus,"Current takes precedence");File.WriteAllText(current,"{corrupt");Check(store.Load().Error!=null&&store.Save(new())!=null&&File.ReadAllText(current)=="{corrupt"&&File.ReadAllText(legacy)==original,"Corrupt current preserved, no fallback");}finally{Directory.Delete(dir,true);}});
foreach(var failure in new[]{"mode verification","barrier installation"})foreach(var resume in new[]{"settings resume","clear resume"})Test("Failed "+failure+" stays blocked after "+resume,()=>{var state=new ControllerReadiness();bool caught=false;try{state.InitializeAsync(()=>{if(failure=="mode verification")throw new InvalidOperationException("Mode mismatch");throw new NotSupportedException("Filter unavailable");}).GetAwaiter().GetResult();}catch(Exception e) when(e is InvalidOperationException or NotSupportedException){caught=true;}Check(caught,"Injected initialization failure observed");state.RequestResume(false);state.RequestResume(true);Check(!state.IsInitialized&&!state.CanNavigate,failure+" must remain non-navigable after "+resume);});
Test("Complete initialization permits temporary suspension but permanent faults need replacement",()=>{var state=new ControllerReadiness();state.RequestResume(true);Check(!state.CanNavigate,"Resume before complete initialization must fail closed");state.InitializeAsync(()=>Task.CompletedTask).GetAwaiter().GetResult();Check(state.IsInitialized,"Full guards completed");state.RequestResume(true);Check(state.CanNavigate,"Initialized controller resumes");state.RequestResume(false);Check(state.IsInitialized&&!state.CanNavigate,"Quiescence preserves full guard invariant");state.RequestResume(true);Check(state.CanNavigate,"Clear/settings may resume initialized controller");state.Fail();state.RequestResume(true);Check(!state.IsInitialized&&!state.CanNavigate,"Permanent fault cannot be resumed");bool rejected=false;try{state.InitializeAsync(()=>Task.CompletedTask).GetAwaiter().GetResult();}catch(InvalidOperationException){rejected=true;}Check(rejected,"Same controller cannot reinitialize after retirement");var replacement=new ControllerReadiness();replacement.InitializeAsync(()=>Task.CompletedTask).GetAwaiter().GetResult();replacement.RequestResume(true);Check(replacement.CanNavigate,"Fully initialized replacement can navigate");state.Dispose();state.RequestResume(true);Check(!state.IsInitialized&&!state.CanNavigate,"Disposed controller cannot resume");});
foreach(var operation in new[]{"rules update","clear all"})Test("Frame or nonfatal failure retires raw controller before "+operation,()=>{var trace=new List<string>();var posted=new Queue<Action>();var ownership=new ControllerOwnership(()=>trace.Add("dispose actual controller"));ownership.Attach();var readiness=new ControllerReadiness();readiness.InitializeAsync(()=>Task.CompletedTask).GetAwaiter().GetResult();readiness.Fail();ownership.RequestRetirement(posted.Enqueue,error=>throw error);Check(!readiness.IsInitialized&&ownership.HasController&&trace.Count==0,"Callback invalidates navigation but retains raw cleanup ownership until dispatch");ownership.QuiesceAsync(()=>{trace.Add("quiesce live document");return Task.CompletedTask;}).GetAwaiter().GetResult();Check(!ownership.HasController&&trace.SequenceEqual(new[]{"dispose actual controller"}),"Operation cannot finish while failed top-level document remains alive");while(posted.TryDequeue(out var retire))retire();Check(trace.Count==1,"Queued retirement must not double-dispose");});
Test("Failed controller disposal cannot be mistaken for completed quiescence",()=>{var ownership=new ControllerOwnership(()=>throw new InvalidOperationException("Native dispose failed"));ownership.Attach();var queue=new Queue<Action>();int failedRetire=0;ownership.RequestRetirement(queue.Enqueue,_=>failedRetire++);queue.Dequeue()();bool failedQuiesce=false;try{ownership.QuiesceAsync(()=>Task.CompletedTask).GetAwaiter().GetResult();}catch(InvalidOperationException){failedQuiesce=true;}Check(failedRetire==1&&failedQuiesce&&ownership.HasController,"Unverified retirement retains raw owner and makes subsequent operation fail");});
Test("Clear all requires the used closed normal profile when only private remains",()=>{var gate=new ProfileOperationGate();var privateOwner=new CleanupFixture(true);var expected=ProfileCleanupCoordinator.ExpectedProfiles(true,[true]);var ok=ProfileCleanupCoordinator.ClearAsync(expected,mode=>Task.FromResult<CleanupFixture?>(mode?privateOwner:null),(mode,owner)=>owner.Private==mode&&owner.Verified,()=>Task.CompletedTask,owner=>{owner.Clears++;return Task.CompletedTask;},()=>{},gate,TimeSpan.FromSeconds(1)).GetAwaiter().GetResult();Check(!ok&&gate.IsBlocked&&gate.RequiresRestart&&privateOwner.Clears==0,"Missing normal owner must block whole clear before any deletion and require restart");});
Test("Complete verified profile set quiesces before clearing every expected owner",()=>{var gate=new ProfileOperationGate();var normal=new CleanupFixture(false);var privateOwner=new CleanupFixture(true);var trace=new List<string>();var ok=ProfileCleanupCoordinator.ClearAsync(ProfileCleanupCoordinator.ExpectedProfiles(true,[true]),mode=>Task.FromResult<CleanupFixture?>(mode?privateOwner:normal),(mode,owner)=>owner.Private==mode&&owner.Verified,()=>{trace.Add("quiesce all controllers");return Task.CompletedTask;},owner=>{Check(trace.Count>0,"Quiesce precedes deletion");owner.Clears++;return Task.CompletedTask;},()=>trace.Add("restore safety"),gate,TimeSpan.FromSeconds(1)).GetAwaiter().GetResult();Check(ok&&normal.Clears==1&&privateOwner.Clears==1&&!gate.IsBlocked&&trace[^1]=="restore safety","All expected owners cleared exactly once before success");});
Test("Profile owner lost while quiescing cannot produce a successful clear",()=>{var gate=new ProfileOperationGate();var owner=new CleanupFixture(false);int passes=0;var ok=ProfileCleanupCoordinator.ClearAsync([false],_=>Task.FromResult<CleanupFixture?>(owner),(_,item)=>item.Verified,()=>{if(++passes==2)owner.Verified=false;return Task.CompletedTask;},item=>{item.Clears++;return Task.CompletedTask;},()=>{},gate,TimeSpan.FromSeconds(1)).GetAwaiter().GetResult();Check(!ok&&gate.IsBlocked&&gate.RequiresRestart&&owner.Clears==0,"Retirement during quiescence invalidates acquired owner before deletion");});
int failed=0;foreach(var (n,a) in tests){try{a();Console.WriteLine("PASS "+n);}catch(Exception e){failed++;Console.WriteLine("FAIL "+n+": "+e.Message);}}Console.WriteLine($"{tests.Count-failed}/{tests.Count} PASS");return failed==0?0:1;

sealed class CleanupFixture(bool isPrivate){public bool Private {get;}=isPrivate;public bool Verified {get;set;}=true;public int Clears {get;set;}}
